{
  "title": "进水与猜疑",
  "synopsis": "老街广播站电源进水短路，周野急于播音发预警，林岚坚持断电排查。在用万用表打破人为破坏的猜疑后，两人在核对线路与清理积水中逐渐缓和关系，却在推闸瞬间遭遇水管破裂的二次危机。",
  "preview_blurb": "暴雨将至，老街广播站突发短路冒烟。面对急于播音的周野，维修员林岚能否在危机中查明故障真相？",
  "scenes": [
    {
      "title": "黄金钩子与矛盾爆发",
      "location": "老街广播站检修台",
      "dramatic_goal": "展现电源短路危机，确立周野的急躁与林岚的专业坚持，引出人为破坏的猜疑。",
      "lines": [
        {
          "kind": "sfx",
          "speaker_role_id": null,
          "text": "刺耳电流爆音，设备冒烟滋滋声，重物砸地闷响",
          "audio_cue_ref": "sfx_short_circuit_burst",
          "performance_hint": "突发、刺耳，瞬间拉高紧张感"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "哎！怎么又冒烟了！林岚，暴雨马上就来，街坊们还等着听预警，能不能先强行推闸？",
          "audio_cue_ref": "sfx_rain_background",
          "performance_hint": "焦急、语速快，带着迫切的责任感"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "断电。电源接头进水短路，强行推闸会烧毁主板。",
          "audio_cue_ref": "sfx_switch_off",
          "performance_hint": "冷静、干脆，不容置疑"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "可这水迹……不会是哪个熊孩子故意泼水搞破坏吧？我这就去查监控！",
          "audio_cue_ref": "sfx_footsteps_rush",
          "performance_hint": "多疑、急躁，试图用假设掩盖无措"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "站住。拿好万用表。",
          "audio_cue_ref": "sfx_tool_clank",
          "performance_hint": "严厉打断，祈使句，确立主导权"
        }
      ]
    },
    {
      "title": "数据证伪与拉扯缓和",
      "location": "配电箱前",
      "dramatic_goal": "林岚用客观数据打破猜疑，两人在共同核对图纸与清理积水中触及旧伤，关系微妙缓和。",
      "lines": [
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "按住红表笔，别动。",
          "audio_cue_ref": "sfx_wire_strip",
          "performance_hint": "指令清晰，动作利落"
        },
        {
          "kind": "sfx",
          "speaker_role_id": null,
          "text": "万用表表针归零的滴声",
          "audio_cue_ref": "sfx_multimeter_beep",
          "performance_hint": "清脆、客观，打破猜疑的证据"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "听见没？阻值归零。这是防水胶圈老化碎裂导致的自然渗水，不是人为泼水。",
          "audio_cue_ref": null,
          "performance_hint": "公事公办，用数据说话"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "啊？真是老化啊……咳，那什么，我这不是急糊涂了嘛。这胶圈碎得跟饼干渣似的。",
          "audio_cue_ref": "sfx_rubber_crumble",
          "performance_hint": "尴尬、自嘲，试图缓和气氛"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "手电打亮配电箱。我报编号，你核对图纸。",
          "audio_cue_ref": "sfx_flashlight_click",
          "performance_hint": "不接情绪茬，直接推进工作"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "好嘞。一号端子，红线，对。二号端子……",
          "audio_cue_ref": "sfx_paper_rustle",
          "performance_hint": "配合默契，语速放缓"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "擦擦地上的积水，别滑倒。",
          "audio_cue_ref": "sfx_cloth_throw",
          "performance_hint": "克制地关心，动作代替言语"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "谢谢啊。当年要不是我瞎催，你也不至于气得走人。今天算我欠你的。",
          "audio_cue_ref": "sfx_wiping_water",
          "performance_hint": "借机坦白旧伤，语气真诚带点愧疚"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "看图纸。三号端子，黑线。",
          "audio_cue_ref": null,
          "performance_hint": "回避情感话题，用工作指令掩饰内心波动"
        }
      ]
    },
    {
      "title": "二次反转与危机降临",
      "location": "检修台与老旧水管下方",
      "dramatic_goal": "利用旧工具完成修复，但在推闸验收瞬间遭遇水管破裂，危机升级打断约定。",
      "lines": [
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "主线路老化，得重新走线。但我没带防水胶布。",
          "audio_cue_ref": null,
          "performance_hint": "陈述客观困难"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "等等！你以前留下的旧工具箱里好像有！我找找……找到了！你看这规格行不行？",
          "audio_cue_ref": "sfx_toolbox_open",
          "performance_hint": "急切、惊喜，渴望提供帮助"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "线径匹配。递给我。",
          "audio_cue_ref": "sfx_tape_tear",
          "performance_hint": "确认无误，接纳对方的帮助"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "接好了。准备推闸。",
          "audio_cue_ref": "sfx_switch_on",
          "performance_hint": "专业、沉稳"
        },
        {
          "kind": "sfx",
          "speaker_role_id": null,
